attempts.sparql:
PREFIX gleif-L1: <https://www.gleif.org/ontology/L1/>
PREFIX gleif-base: <https://www.gleif.org/ontology/Base/>
PREFIX gleif-re: <https://www.gleif.org/ontology/ReportingException/>
PREFIX kgx: <https://example.org/gleif-kg/ontology/>

SELECT ?parentLEI ?exceptionCategory ?reason WHERE {
  # Find the entity with legal name "M-M FRANCE"
  ?entity a gleif-L1:RegisteredEntity ;
          gleif-L1:hasLegalName "M-M FRANCE" ;
          gleif-L1:LEI ?lei .

  OPTIONAL {
    # If it reports an ultimate consolidation parent
    ?entity kgx:hasUltimateConsolidationParent ?parent .
    BIND(STR(?parent) AS ?parentLEI)
  }

  OPTIONAL {
    # If it reports a reporting exception instead
    ?exception gleif-re:hasReportingEntity ?entity ;
               a gleif-re:UltimateConsolidationReportingException ;
               gleif-re:hasExceptionReason ?reason .
    BIND("UltimateConsolidationReportingException" AS ?exceptionCategory)
  }
} LIMIT 1

